'use strict';

const fs = require('node:fs/promises');
const path = require('node:path');

const README_PATH = path.join(__dirname, 'README.md');
const OUTPUT_PATH = path.join(__dirname, 'results', 'status.json');

async function readEndpoint() {
  const readme = await fs.readFile(README_PATH, 'utf8');
  const urls = readme.match(/https?:\/\/[^\s)"']+/g) || [];
  const endpoint = urls.find((url) => url.endsWith('/status'));
  if (!endpoint) {
    throw new Error(`No /status endpoint found in ${README_PATH}`);
  }
  return endpoint;
}

async function main() {
  const endpoint = await readEndpoint();
  console.log(`GET ${endpoint}`);

  const response = await fetch(endpoint);
  const body = await response.json();
  const status = body && body.status !== undefined ? body.status : response.status;

  if (status !== 200) {
    throw new Error(`Expected status=200, got status=${status} (HTTP ${response.status})`);
  }

  await fs.mkdir(path.dirname(OUTPUT_PATH), { recursive: true });
  await fs.writeFile(OUTPUT_PATH, `${JSON.stringify({ status }, null, 2)}\n`);

  console.log(`status=${status}`);
  console.log(`Wrote ${OUTPUT_PATH}`);
}

main().catch((error) => {
  console.error(`client failed: ${error.message}`);
  process.exitCode = 1;
});

